def minmax(a, b):
    if a < b:
        return (a, b)
    else:
        return (b, a)

print(minmax(3, 7))

def total(*nums):
    return sum(nums)

print(total(1, 2, 3, 4))

def double(x):
    return x * 2

def quad(x):
    return double(double(x))

print(quad(3))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

